CREATE COLUMN TABLE "TEST_AP"."OUGP" ("UgpEntry" INTEGER CS_INT NOT NULL , "UgpCode" NVARCHAR(20) NOT NULL , "UgpName" NVARCHAR(100), "BaseUom" INTEGER CS_INT, "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "CreateDate" LONGDATE CS_LONGDATE, "Locked" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("UgpEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OUGP_CODE" ON "TEST_AP"."OUGP" ( "UgpCode" ASC );
CREATE INDEX "OUGP_NAME" ON "TEST_AP"."OUGP" ( "UgpName" ASC )